// Verify the reassoc and bitwise tables' rules with the options of the recorded evidence ({random: 1e6, seed: 7,
// exhaustive32: true}) and add their records to src/typed/rules/evidence.ts, keeping every existing record as
// generated by IRWB-006's scripts/04-verify-rules.mjs (re-running that is 66 minutes for unchanged rules).
import { readFileSync, writeFileSync } from 'node:fs';
const root = new URL('../../../../../../', import.meta.url);
const { verifyRule } = await import(new URL('dist/typed/rules/verify.js', root));
const { RULE_EVIDENCE, EVIDENCE_OPTIONS } = await import(new URL('dist/typed/rules/evidence.js', root));
const { REASSOC_RULES } = await import(new URL('dist/typed/rules/reassoc.js', root));
const { BITWISE_RULES } = await import(new URL('dist/typed/rules/bitwise.js', root));
const { ruleFingerprint } = await import(new URL('dist/typed/rules/verify.js', root));
const NEW = [...REASSOC_RULES.rules, ...BITWISE_RULES.rules];
const file = new URL('src/typed/rules/evidence.ts', root);
const table = { ...RULE_EVIDENCE };
const t0 = performance.now();
for (const r of NEW) {
  // a record for the rule's current fingerprint is kept (verified by an earlier run of this script)
  if (table[r.name]?.fingerprint === ruleFingerprint(r)) continue;
  const e = verifyRule(r, EVIDENCE_OPTIONS);
  if (e.verdict !== 'sound') throw new Error(`${r.name}: ${JSON.stringify(e)}`);
  table[r.name] = e;
  console.log(r.name, e.verdict, e.strength, e.methods.map(m => `${m.method}:${m.verdict}`).join(' '));
}
const ms = Math.round(performance.now() - t0);
const src = readFileSync(file, 'utf8');
const head = src.slice(0, src.indexOf('export const RULE_EVIDENCE'));
const original = head.slice(0, head.indexOf(' rule no longer matches its record, so an edited rule must be verified again.'));
const header = `${original} rule no longer matches its record, so an edited rule must be verified again.
 *
 * The reassoc and bitwise tables' records (IRWB-037-F) were added by
 * ttmp/2026/11/27/IRWB-037-F--…/scripts/06-record-evidence.mjs with the same options.
 */
import type { RuleEvidence } from './verify.js';

export const EVIDENCE_OPTIONS = ${JSON.stringify(EVIDENCE_OPTIONS)} as const;
`;
writeFileSync(file, `${header}export const RULE_EVIDENCE: Readonly<Record<string, RuleEvidence>> = ${JSON.stringify(table, null, 2)};\n`);
console.log(JSON.stringify({ rules: Object.keys(table).length, ms }));
